  /// Guards against duplicate initialization requests (e.g. from MCP Inspector
  /// which may send `initialize` more than once for HTTP endpoints).
  bool _isInitialized = false;
  InitializeResult? _initializeResult;

  @override
  FutureOr<InitializeResult> initialize(InitializeRequest request) async {
    if (_isInitialized) return _initializeResult!;
    _isInitialized = true;
    final result = await super.initialize(request);
    _initializeResult = result;
    return result;
  }

  FutureOr<CallToolResult> _onvifConnect(CallToolRequest request) async {
    try {
      final host = request.arguments!['host'] as String;
      final username = request.arguments!['username'] as String;

      final result = await easy_onvif_mcp_server.EasyOnvifMcpServer().connect(
        host: host,
        username: username,
      );
      return CallToolResult(
        content: [TextContent(text: _serializeResult(result))],
      );
    } catch (e, st) {
      if (_logErrors) {
        io.stderr.writeln('[easy_api] onvif_connect: $e');
        io.stderr.writeln(st);
        await io.stderr.flush();
      }
      return CallToolResult(
        content: [
          TextContent(text: 'An error occurred while processing the request.'),
        ],
        isError: true,
      );
    }
  }

